using System.IO;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using PinPop;
public static class SplashScenePreviewSetup {
 public const string AssetPath="Assets/Resources/Startup/splash-preview.png";
 [InitializeOnLoadMethod] static void Install(){EditorApplication.delayCall+=EnsureActive;EditorApplication.playModeStateChanged+=state=>{if(state==PlayModeStateChange.EnteredEditMode)EditorApplication.delayCall+=EnsureActive;};}
 public static void EnsureActive(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)return;var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/PinPop.unity"||!File.Exists(AssetPath))return;var previews=Object.FindObjectsByType<PinPopSplashPreview>(FindObjectsInactive.Include,FindObjectsSortMode.None);if(previews.Length==0){Create(false);EditorSceneManager.MarkSceneDirty(scene);}else foreach(var p in previews)p.gameObject.SetActive(true);}
 public static Sprite Bake(){Directory.CreateDirectory(Path.GetDirectoryName(AssetPath));var go=new GameObject("Temporary splash preview baker");var splash=go.AddComponent<PinPopSplash>();splash.BuildEditorPreview();var rt=new RenderTexture(600,1000,24);var old=RenderTexture.active;try{splash.SplashCamera.targetTexture=rt;splash.SplashCamera.aspect=.6f;splash.FitTo(600,1000);Canvas.ForceUpdateCanvases();splash.SplashCamera.Render();Canvas.ForceUpdateCanvases();splash.SplashCamera.Render();RenderTexture.active=rt;var image=new Texture2D(600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,600,1000),0,0);image.Apply();File.WriteAllBytes(AssetPath,image.EncodeToPNG());Object.DestroyImmediate(image);}finally{splash.SplashCamera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(rt);Object.DestroyImmediate(go);}AssetDatabase.ImportAsset(AssetPath);var importer=(TextureImporter)AssetImporter.GetAtPath(AssetPath);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.mipmapEnabled=false;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.npotScale=TextureImporterNPOTScale.None;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(AssetPath);}
 public static void ValidateAndCapture(){EditorSceneManager.OpenScene("Assets/Scenes/PinPop.unity");var previews=Object.FindObjectsByType<PinPopSplashPreview>(FindObjectsSortMode.None);if(previews.Length!=1||!previews[0].GetComponent<Camera>().isActiveAndEnabled||previews[0].GetComponentInChildren<Image>().sprite==null)throw new System.Exception("Serialized startup preview is missing its camera or artwork");Directory.CreateDirectory("Documentation/VideoReview");var camera=previews[0].GetComponent<Camera>();var rt=new RenderTexture(600,1000,24);var old=RenderTexture.active;camera.targetTexture=rt;camera.aspect=.6f;Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;var image=new Texture2D(600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,600,1000),0,0);image.Apply();File.WriteAllBytes("Documentation/VideoReview/editor-scene-preview.png",image.EncodeToPNG());camera.targetTexture=null;camera.ResetAspect();RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);File.WriteAllText("Documentation/VideoReview/editor-scene-verification.json","{\"serializedCamera\":true,\"serializedArtwork\":true,\"cameraCount\":"+Camera.allCamerasCount+"}");Debug.Log("PINPOP: Serialized edit-mode splash camera verified.");}
 public static void Create(bool bake=true){var sprite=bake?Bake():AssetDatabase.LoadAssetAtPath<Sprite>(AssetPath);if(sprite==null)return;var root=new GameObject("PinPop splash scene preview");root.AddComponent<PinPopSplashPreview>();var camera=root.AddComponent<Camera>();camera.orthographic=true;camera.orthographicSize=5;camera.depth=90;camera.cullingMask=1<<27;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Art.Hex("F4F0E4");camera.transform.position=new Vector3(0,0,-5);camera.nearClipPlane=.1f;camera.farClipPlane=10;
  var go=new GameObject("Editor startup canvas",typeof(RectTransform),typeof(Canvas));go.layer=27;go.transform.SetParent(root.transform,false);var canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;canvas.sortingOrder=900;var image=new GameObject("Editor startup artwork",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));image.layer=27;image.transform.SetParent(go.transform,false);var rect=image.GetComponent<RectTransform>();rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.offsetMin=rect.offsetMax=Vector2.zero;var graphic=image.GetComponent<Image>();graphic.sprite=sprite;graphic.preserveAspect=true;graphic.raycastTarget=false;
 }
}
public sealed class SplashPreviewAssetRefresh:AssetPostprocessor {
 static void OnPostprocessAllAssets(string[] imported,string[] deleted,string[] moved,string[] from){if(System.Array.Exists(imported,p=>p==SplashScenePreviewSetup.AssetPath))EditorApplication.delayCall+=SplashScenePreviewSetup.EnsureActive;}
}
